package org.example.mediator.chat;

import javafx.application.Application;
import javafx.stage.Stage;
import org.example.mediator.chat.domain.ChatMediator;
import org.example.mediator.chat.domain.ChatRoomMediator;
import org.example.mediator.chat.ui.ChatWindowController;

import java.util.ArrayList;
import java.util.List;

public class ChatApplication extends Application {
    @Override
    public void start(Stage primaryStage) {
        ChatMediator mediator = new ChatRoomMediator();

        List<ChatWindowController> controllers = new ArrayList<>();
        controllers.add(new ChatWindowController("Alice", mediator));
        controllers.add(new ChatWindowController("Bob", mediator));
        controllers.add(new ChatWindowController("Carol", mediator));

        for (ChatWindowController controller : controllers) {
            mediator.registerClient(controller);
        }

        List<String> usernames = mediator.getRegisteredUsernames();

        controllers.get(0).show(primaryStage, usernames);
        for (int i = 1; i < controllers.size(); i++) {
            controllers.get(i).show(new Stage(), usernames);
        }
    }
}

package org.example.mediator.chat;

public final class Main {
    private Main() {
    }

    public static void main(String[] args) {
        ChatApplication.launch(ChatApplication.class, args);
    }
}

package org.example.mediator.chat.domain;

public interface ChatClient {
    String getUsername();

    void receive(ChatMessage message);
}

package org.example.mediator.chat.domain;

import java.util.List;

public interface ChatMediator {
    void registerClient(ChatClient client);

    void sendPrivateMessage(String senderUsername, String recipientUsername, String content);

    List<String> getRegisteredUsernames();
}

package org.example.mediator.chat.domain;

import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Objects;

public record ChatMessage(
        String senderUsername,
        String recipientUsername,
        String content,
        LocalDateTime sentAt
) {
    private static final DateTimeFormatter TIME_FORMAT = DateTimeFormatter.ofPattern("HH:mm:ss");

    public ChatMessage {
        senderUsername = requireNonBlank(senderUsername, "senderUsername");
        recipientUsername = requireNonBlank(recipientUsername, "recipientUsername");
        content = requireNonBlank(content, "content");
        sentAt = Objects.requireNonNull(sentAt, "sentAt must not be null");
    }

    public String toDisplayLine() {
        return "[" + sentAt.format(TIME_FORMAT) + "] "
                + senderUsername + " -> " + recipientUsername + ": " + content;
    }

    private static String requireNonBlank(String value, String fieldName) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(fieldName + " must not be blank");
        }
        return value.trim();
    }
}

package org.example.mediator.chat.domain;

import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

public class ChatRoomMediator implements ChatMediator {
    private final Map<String, ChatClient> clientsByUsername = new LinkedHashMap<>();

    @Override
    public void registerClient(ChatClient client) {
        ChatClient checkedClient = Objects.requireNonNull(client, "client must not be null");
        String username = checkedClient.getUsername();

        if (username == null || username.isBlank()) {
            throw new IllegalArgumentException("Client username must not be blank");
        }

        if (clientsByUsername.containsKey(username)) {
            throw new IllegalArgumentException("Username already registered: " + username);
        }

        clientsByUsername.put(username, checkedClient);
    }

    @Override
    public void sendPrivateMessage(String senderUsername, String recipientUsername, String content) {
        String sender = requireNonBlank(senderUsername, "senderUsername");
        String recipient = requireNonBlank(recipientUsername, "recipientUsername");
        String cleanedContent = requireNonBlank(content, "content");

        ChatClient senderClient = clientsByUsername.get(sender);
        if (senderClient == null) {
            throw new IllegalArgumentException("Unknown sender: " + sender);
        }

        ChatClient recipientClient = clientsByUsername.get(recipient);
        if (recipientClient == null) {
            throw new IllegalArgumentException("Unknown recipient: " + recipient);
        }

        ChatMessage message = new ChatMessage(sender, recipient, cleanedContent, LocalDateTime.now());
        senderClient.receive(message);

        if (!sender.equals(recipient)) {
            recipientClient.receive(message);
        }
    }

    @Override
    public List<String> getRegisteredUsernames() {
        return List.copyOf(new ArrayList<>(clientsByUsername.keySet()));
    }

    private static String requireNonBlank(String value, String fieldName) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(fieldName + " must not be blank");
        }

        return value.trim();
    }
}

package org.example.mediator.chat.ui;

import javafx.scene.Scene;
import javafx.stage.Stage;
import org.example.mediator.chat.domain.ChatClient;
import org.example.mediator.chat.domain.ChatMediator;
import org.example.mediator.chat.domain.ChatMessage;

import java.util.List;
import java.util.Objects;

public class ChatWindowController implements ChatClient {
    private final String username;
    private final ChatMediator mediator;
    private final ChatWindowView view;

    public ChatWindowController(String username, ChatMediator mediator) {
        if (username == null || username.isBlank()) {
            throw new IllegalArgumentException("username must not be blank");
        }

        this.username = username.trim();
        this.mediator = Objects.requireNonNull(mediator, "mediator must not be null");
        this.view = new ChatWindowView();

        this.view.sendButton().setOnAction(event -> sendMessage());
        this.view.messageInput().setOnAction(event -> sendMessage());
    }

    public void show(Stage stage, List<String> allUsernames) {
        Objects.requireNonNull(stage, "stage must not be null");
        setupRecipients(allUsernames);

        stage.setTitle("Chat - " + username);
        stage.setScene(new Scene(view.rootNode(), 520, 360));
        stage.show();
    }

    @Override
    public String getUsername() {
        return username;
    }

    @Override
    public void receive(ChatMessage message) {
        view.conversationArea().appendText(message.toDisplayLine() + System.lineSeparator());
    }

    private void setupRecipients(List<String> usernames) {
        view.recipientSelector().getItems().setAll(usernames.stream()
                .filter(name -> !username.equals(name))
                .toList());

        if (!view.recipientSelector().getItems().isEmpty()) {
            view.recipientSelector().getSelectionModel().selectFirst();
        }
    }

    private void sendMessage() {
        String recipient = view.recipientSelector().getValue();
        String content = view.messageInput().getText();

        if (recipient == null || recipient.isBlank()) {
            return;
        }

        if (content == null || content.isBlank()) {
            return;
        }

        mediator.sendPrivateMessage(username, recipient, content);
        view.messageInput().clear();
    }
}

package org.example.mediator.chat.ui;

import javafx.geometry.Insets;
import javafx.scene.Parent;
import javafx.scene.control.Button;
import javafx.scene.control.ComboBox;
import javafx.scene.control.TextArea;
import javafx.scene.control.TextField;
import javafx.scene.layout.HBox;
import javafx.scene.layout.Priority;
import javafx.scene.layout.VBox;

public class ChatWindowView {
    private final TextArea conversationArea = new TextArea();
    private final ComboBox<String> recipientSelector = new ComboBox<>();
    private final TextField messageInput = new TextField();
    private final Button sendButton = new Button("Send");
    private final VBox root;

    public ChatWindowView() {
        conversationArea.setEditable(false);
        conversationArea.setWrapText(true);
        conversationArea.setPromptText("Messages appear here...");

        recipientSelector.setPromptText("Recipient");
        recipientSelector.setPrefWidth(120);

        messageInput.setPromptText("Type a message");
        HBox.setHgrow(messageInput, Priority.ALWAYS);

        HBox controls = new HBox(8, recipientSelector, messageInput, sendButton);
        root = new VBox(10, conversationArea, controls);
        root.setPadding(new Insets(12));
        VBox.setVgrow(conversationArea, Priority.ALWAYS);
    }

    public Parent rootNode() {
        return root;
    }

    public TextArea conversationArea() {
        return conversationArea;
    }

    public ComboBox<String> recipientSelector() {
        return recipientSelector;
    }

    public TextField messageInput() {
        return messageInput;
    }

    public Button sendButton() {
        return sendButton;
    }
}
